#!/bin/bash
# Submit from the frozen snapshot root, supplying account and partition
# privately to sbatch. The runtime environment is generated by package_pilot.py.
# Native BF16 weights span two GPUs. Thinking uses the same 4096-token cap as
# the API study; allow a longer allocation for reasoning than the Gemma runs.
#SBATCH --job-name=passgame-qwen27b
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --gres=gpu:a100:2
#SBATCH --cpus-per-task=8
#SBATCH --mem=96G
#SBATCH --time=08:00:00
set -euo pipefail
: "${SLURM_SUBMIT_DIR:?Submit this script from the frozen snapshot root}"
export VLLM_EXTRA_ARGS="--tensor-parallel-size 2 --reasoning-parser qwen3 --language-model-only"
exec bash "$SLURM_SUBMIT_DIR/scripts/run_galvani_fixed_start.sh"
